CREATE FUNCTION public.initialize_waiver_priority() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.draft_status='complete' AND OLD.draft_status<>'complete' THEN INSERT INTO waiver_priority(league_id,team_id,rank) SELECT NEW.id,t.id,row_number() OVER(ORDER BY t.draft_order DESC) FROM teams t WHERE t.league_id=NEW.id ON CONFLICT(team_id) DO UPDATE SET rank=excluded.rank; END IF; RETURN NEW; END $$;
CREATE TRIGGER waiver_priority_after_draft AFTER UPDATE ON public.leagues FOR EACH ROW EXECUTE FUNCTION public.initialize_waiver_priority();
CREATE OR REPLACE FUNCTION public.cancel_waiver_claim(cid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid; BEGIN SELECT w.league_id INTO lid FROM waiver_claims c JOIN player_waivers w ON w.id=c.waiver_id JOIN teams t ON t.id=c.team_id WHERE c.id=cid AND t.owner_id=auth.uid(); IF lid IS NULL THEN RAISE EXCEPTION 'Claim not found'; END IF; PERFORM 1 FROM leagues WHERE id=lid FOR UPDATE; UPDATE waiver_claims SET status='cancelled' WHERE id=cid AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'This claim has already been processed'; END IF; END $$;
CREATE FUNCTION public.guard_trade_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM teams WHERE id=NEW.from_team AND league_id=NEW.league_id) OR NOT EXISTS(SELECT 1 FROM teams WHERE id=NEW.to_team AND league_id=NEW.league_id) THEN RAISE EXCEPTION 'Both teams must belong to this league'; END IF; IF NEW.parent_trade IS NOT NULL AND NOT EXISTS(SELECT 1 FROM player_trades WHERE id=NEW.parent_trade AND league_id=NEW.league_id AND from_team=NEW.to_team AND to_team=NEW.from_team) THEN RAISE EXCEPTION 'Invalid counteroffer'; END IF; RETURN NEW; END $$;
CREATE TRIGGER trade_link_guard BEFORE INSERT ON public.player_trades FOR EACH ROW EXECUTE FUNCTION public.guard_trade_links();
REVOKE ALL ON FUNCTION public.initialize_waiver_priority(),public.guard_trade_links() FROM PUBLIC;